package org.vef.mlkitlab;
import org.junit.Test;import static org.junit.Assert.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.json.*;
public class ParserPerformanceTest {
 static final Path ORIGINAL=Paths.get("recovery/diagnostic-022-before.jar");
 static List<Object> copy(List<TableParser.Token> tokens,java.lang.reflect.Constructor<?> ctor)throws Exception{List<Object> r=new ArrayList<>();for(TableParser.Token t:tokens)r.add(ctor.newInstance(t.text,t.left,t.top,t.right,t.bottom,t.confidence,t.id));return r;}
 static List<Integer> ids(List<?> tokens)throws Exception{List<Integer> r=new ArrayList<>();for(Object t:tokens)r.add(t.getClass().getField("id").getInt(t));return r;}
 static void compare(Object old,TableParser.Result current)throws Exception{
  String[][] values=(String[][])old.getClass().getField("cells").get(old),status=(String[][])old.getClass().getField("status").get(old),reasons=(String[][])old.getClass().getField("reasons").get(old);
  List<?>[][] evidence=(List<?>[][])old.getClass().getField("evidence").get(old);Set<Integer> used=new HashSet<>();
  assertEquals(old.getClass().getField("rowCount").getInt(old),current.rowCount);
  for(int r=0;r<20;r++)for(int c=0;c<5;c++){
   if(!values[r][c].isEmpty()){assertEquals("retained value",values[r][c],current.cells[r][c]);assertEquals(status[r][c],current.status[r][c]);assertEquals(reasons[r][c],current.reasons[r][c]);assertEquals(ids(evidence[r][c]),ids(current.evidence[r][c]));}
   for(TableParser.Token t:current.evidence[r][c])if(t.id>=0)assertTrue("Duplicate token "+t.id,used.add(t.id));
  }
 }
 @Test public void realFold275PreservesValuesFlagsAndEvidence()throws Exception{
  String file=System.getProperty("mlkit.fold.report","");org.junit.Assume.assumeTrue("Supply MLKIT_FOLD_REPORT",!file.isEmpty());JSONObject report=new JSONObject(new String(Files.readAllBytes(Paths.get(file)),java.nio.charset.StandardCharsets.UTF_8));List<TableParser.Token> words=RecoveredDiagnosticTest.readTokens(report.getJSONArray("tokensInOrientedOcrPixels")),lines=RecoveredDiagnosticTest.readTokens(report.getJSONArray("linesInOrientedOcrPixels"));assertEquals(275,words.size());assertEquals(194,lines.size());
  Path log=Files.createTempFile("fold-parser", ".jsonl");RunJournal journal=new RunJournal(log.toFile());journal.begin("PARSER_INCLUDING_INTERNAL_VALIDATION",5000);
  long start=System.nanoTime();TableParser.Result result=ParserRuntime.parse(words,lines,journal);double after=(System.nanoTime()-start)/1e6;
  assertEquals(20,result.rowCount);assertEquals(100,result.associatedCells);assertEquals(41,result.coherentCells);assertEquals(58,result.reviewCells);assertEquals(1,result.invalidCells);for(int r=0;r<20;r++){assertFalse(result.cells[r][4].isEmpty());assertTrue(result.reasons[r][4].contains("HEADER_OCR_ALIAS_REQUIRES_REVIEW"));}
  long oldStart=System.nanoTime();try(URLClassLoader old=new URLClassLoader(new URL[]{ORIGINAL.toUri().toURL()},null)){Class<?> token=old.loadClass("org.vef.mlkitlab.TableParser$Token");java.lang.reflect.Constructor<?> ctor=token.getConstructor(String.class,float.class,float.class,float.class,float.class,float.class,int.class);Object previous=old.loadClass("org.vef.mlkitlab.TableParser").getMethod("parse",List.class,List.class).invoke(null,copy(words,ctor),copy(lines,ctor));compare(previous,result);}
  double before=(System.nanoTime()-oldStart)/1e6;String text=new String(Files.readAllBytes(log),java.nio.charset.StandardCharsets.UTF_8);
  for(String phase:Arrays.asList("DATE_ANCHORS","HEADER_CANDIDATES","HEADER_SELECTION_AND_GEOMETRY","TEXT_FRAGMENT_GROUPING","CELL_ASSOCIATION","CELL_VALUE_ASSEMBLY_AND_INTERNAL_VALIDATION"))assertTrue(phase,text.contains(phase));assertTrue(text.contains("PARSER_SUMMARY"));
  System.out.printf(Locale.ROOT,"FOLD 275 JVM: before=%.3fms after=%.3fms (includes fsync); 20 rows, 100 associated, 41 coherent, 58 review, 1 invalid, 0 missing. All previously associated values, flags, reasons and evidence unchanged; new BIL header values require review. Not device timing or an accuracy oracle.%n%s",before,after,text);Files.delete(log);
 }
 @Test public void cacheInvalidatesMergedGroupsAndKeepsUnicodeSemantics(){ParserRuntime.beginGroups();try{List<TableParser.Token> g=new ArrayList<>();g.add(new TableParser.Token("É",0,0,5,10,.9f,1));TableParser.Token a=ParserRuntime.cachedBounds(g);assertSame(a,ParserRuntime.cachedBounds(g));g.add(new TableParser.Token("PORT",8,0,20,10,.7f,2));TableParser.Token b=ParserRuntime.cachedBounds(g);assertNotSame(a,b);assertEquals("É PORT",b.text);assertEquals(20f,b.right,0);assertEquals(.7f,b.confidence,0);for(String s:Arrays.asList("123","É","港","A\nB","\nÉ","", "𐐀"))assertEquals(s.matches(".*\\p{L}.*"),ParserRuntime.hasLetters(s,".*\\p{L}.*"));}finally{ParserRuntime.endGroups();}}
 @Test public void subphasesNeverResetDeadlines()throws Exception{Path f=Files.createTempFile("parser-deadline", ".jsonl");AtomicLong c=new AtomicLong();RunJournal j=new RunJournal(f.toFile(),c::get);j.begin("PARSER_INCLUDING_INTERNAL_VALIDATION",5000);c.set(4500);ParserRuntime.parse(Collections.emptyList(),Collections.emptyList(),j);c.set(5000);assertEquals("STAGE_TIMEOUT at PARSER_INCLUDING_INTERNAL_VALIDATION",j.deadlineReason());c.set(15000);assertEquals("TOTAL_TIMEOUT at PARSER_INCLUDING_INTERNAL_VALIDATION",j.deadlineReason());Files.delete(f);}
 @Test public void randomizedGroupingMatchesOriginalOrderAndMembership()throws Exception{Random random=new Random(2202);java.lang.reflect.Method current=TableParser.class.getDeclaredMethod("textGroups",List.class,double.class);current.setAccessible(true);try(URLClassLoader old=new URLClassLoader(new URL[]{ORIGINAL.toUri().toURL()},null)){Class<?> parser=old.loadClass("org.vef.mlkitlab.TableParser"),token=old.loadClass("org.vef.mlkitlab.TableParser$Token");java.lang.reflect.Method baseline=parser.getDeclaredMethod("textGroups",List.class,double.class);baseline.setAccessible(true);java.lang.reflect.Constructor<?> ctor=token.getConstructor(String.class,float.class,float.class,float.class,float.class,float.class,int.class);String[] text={"A","B","É","港","123","456.789","A\nB","", "𐐀"};for(int run=0;run<120;run++){List<TableParser.Token> input=new ArrayList<>();for(int i=0;i<35;i++){float x=random.nextInt(16)*7,y=random.nextInt(6)*14;input.add(new TableParser.Token(text[random.nextInt(text.length)],x,y,x+5,y+10,.5f+random.nextFloat()/2,i));}double slope=(random.nextDouble()-.5)*.1;List<?> a=(List<?>)baseline.invoke(null,copy(input,ctor),slope),b=(List<?>)current.invoke(null,input,slope);assertEquals(a.size(),b.size());for(int i=0;i<a.size();i++)assertEquals("run="+run+" group="+i,ids((List<?>)a.get(i)),ids((List<?>)b.get(i)));}}}
 @Test public void everySyntheticCellMapsToItsObservedRowAndColumn(){
  List<TableParser.Token> words=new ArrayList<>(),headers=new ArrayList<>();
  String[][] expected=new String[20][5];String[] names={"PORT / TERMINAL","B/L DATE","CARGO","SHIP'S FIGURES","B/L FIGURES"};
  for(int c=0;c<5;c++){float x=100+c*200;headers.add(new TableParser.Token(names[c],x-30,15,x+30,25,.99f,-1));}
  for(int r=0;r<20;r++)for(int c=0;c<5;c++){float x=100+c*200,y=60+r*25;String v=c==0?"PORT "+r:c==1?String.format(Locale.ROOT,"%02d.01.2026",r+1):c==2?"CARGO "+r:String.format(Locale.ROOT,"%d.%03d",1000+r*10+c,r*5+c);expected[r][c]=v;words.add(new TableParser.Token(v,x-20,y-5,x+20,y+5,.99f,r*5+c));}
  TableParser.Result result=TableParser.parse(words,headers);assertEquals(20,result.rowCount);assertEquals(100,result.associatedCells);
  for(int r=0;r<20;r++)for(int c=0;c<5;c++){assertEquals("row="+r+" col="+c,expected[r][c],result.cells[r][c]);assertEquals(1,result.evidence[r][c].size());assertEquals(r*5+c,result.evidence[r][c].get(0).id);}
 }
}
